lessons.solution_code:
function createServerConfig(port = 8080) {
    return { port, env: 'development' };
}
module.exports = { createServerConfig };

tests.unittest_code:
const cfg = solution.createServerConfig(3000);
if (cfg.port !== 3000) throw new Error('Port mismatch');
const dflt = solution.createServerConfig();
if (dflt.port !== 8080) throw new Error('Expected default port 8080');
if (cfg.env !== 'development' || dflt.env !== 'development') throw new Error("Expected env 'development'");

